24  // ParseDollars parses "2498.99" or "2498" into cents. More than two decimals is an error.
25  func ParseDollars(s string) (Cents, error) {
26  	whole, frac, _ := strings.Cut(strings.TrimSpace(s), ".")
27  	w, err := strconv.ParseInt(whole, 10, 64)
28  	if err != nil {
29  		return 0, fmt.Errorf("money: bad dollar amount %q", s)
30  	}
31  	if len(frac) > 2 {
32  		return 0, fmt.Errorf("money: %q has more than two decimals", s)
33  	}
34  	for len(frac) < 2 {
35  		frac += "0"
36  	}
37  	f, err := strconv.ParseInt(frac, 10, 64)
38  	if err != nil {
39  		return 0, fmt.Errorf("money: bad dollar amount %q", s)
40  	}
41  	return Cents(w*100 + f), nil
42  }
